// Initial wait: 60s for daily scrapers
await new Promise(r => setTimeout(r, 60000));

const jobId = $('Trigger Daily Sync').first().json.job_id;
if (!jobId) {
  return [{ json: { status: 'error', error: 'No job_id returned from trigger' } }];
}

// Poll up to 10 times, 30s apart (~6 min total after initial 1 min wait)
const MAX_RETRIES = 10;
const POLL_INTERVAL_MS = 30000;

for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: `http://72.61.226.16:5001/job/${jobId}`,
      returnFullResponse: true,
    });

    const body = typeof resp.body === 'string' ? JSON.parse(resp.body) : resp.body;
    const statusCode = resp.statusCode || resp.status || 200;

    if (statusCode === 404) {
      return [{ json: { status: 'error', error: 'Job not found (server may have restarted). Job ID: ' + jobId } }];
    }

    if (body.status === 'completed' || body.status === 'error') {
      return [{ json: body }];
    }

    if (attempt < MAX_RETRIES) {
      await new Promise(r => setTimeout(r, POLL_INTERVAL_MS));
    }
  } catch (e) {
    const errMsg = e.message || String(e);
    if (errMsg.includes('404')) {
      return [{ json: { status: 'error', error: 'Job not found (server may have restarted). Job ID: ' + jobId } }];
    }
    if (errMsg.includes('ECONNREFUSED') || errMsg.includes('ETIMEDOUT')) {
      if (attempt < MAX_RETRIES) {
        await new Promise(r => setTimeout(r, POLL_INTERVAL_MS));
        continue;
      }
      return [{ json: { status: 'error', error: 'Server unreachable after ' + MAX_RETRIES + ' attempts. Job ID: ' + jobId } }];
    }
    return [{ json: { status: 'error', error: errMsg } }];
  }
}

return [{ json: { status: 'error', error: 'Job still running after max poll attempts. Job ID: ' + jobId } }];

